import csv
import json
import os
from decimal import Decimal
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190203", "20190204", "20190205", "20190206", "20190207"]
targets = {
    ("永清站", "通州南站"): "西气东输二线",
    ("普光首站", "达州站"): "川气东送",
}
daily = {}
totals = {pipe: Decimal("0") for pipe in targets.values()}
for date in dates:
    path = DIR / f"{date}_pipeline.csv"
    with path.open("r", encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f)
        rows = list(reader)
    found = {}
    for row in rows:
        key = (row["起点站名"].strip(), row["终点站名"].strip())
        if key in targets:
            pipe = row["管道划分"].strip()
            if pipe != targets[key]:
                raise ValueError(f"Unexpected pipeline {pipe!r} for {key} on {date}")
            value = Decimal(row["管道流量"].strip())
            found[pipe] = value
            totals[pipe] += value
    if len(found) != 2:
        raise ValueError(f"Incomplete target coverage on {date}: {sorted(found)}")
    daily[date] = found
result = {
    "window": {"start": dates[0], "end": dates[-1]},
    "daily": daily,
    "totals": {k: str(v) for k, v in totals.items()},
    "difference": str(totals["川气东送"] - totals["西气东输二线"]),
}
print(json.dumps(result, ensure_ascii=False, indent=2))

